			public const string C001 = "\r\n      IF 'Country of Destination' (box 17a) on HEADER level contains one of the Contracting Parties, or is 'AD' or 'SM'\r\n      THEN TRADER Consignee (box 8) = 'R'\r\n      ELSE TRADER Consignee (box 8) = 'O'\r\n      Contracting parties are :\r\n      the individual non EU common transit country and EU as a group.\r\n    ";
