			public const string C045 = "\r\n      IF 'Declaration type' (box 1) = 'T-'\r\n      THEN 'Declaration type' (ex box 1) = ('T1', 'T2', 'T2F' or 'T2SM')\r\n      ELSE 'Declaration type' (ex box 1) cannot be used\r\n    ";
