			public const string C060 = "\r\n      IF 'Kind of packages' (Box 31) indicates 'BULK' (UNECE rec 21 : 'VQ', 'VG', 'VL','VY','VR' or 'VO')\r\n      THEN 'Marks & numbers of packages' (Box 31) = 'O'\r\n      'Number of packages' (box 31) cannot be used\r\n      'Number of Pieces' (box 31) cannot be used\r\n      ELSE\r\n      IF 'Kind of packages' (Box 31) indicates 'UNPACKED' (UNECE rec 21 : = 'NE','NF', or 'NG')\r\n      THEN 'Marks & numbers of packages' (Box 31) = 'O'\r\n      'Number of packages' cannot be used\r\n      'Number of Pieces' (box 31) = 'R'\r\n      ELSE 'Marks & numbers of packages' (Box 31) = 'R'\r\n      'Number of packages' (box 31) = 'R'\r\n      'Number of Pieces' (box 31) cannot be used\r\n    ";
